import{_ as t,o as d,c as o,a2 as c}from"./chunks/framework.C66fElYV.js";const h=JSON.parse('{"title":"Solon Nami 与 aifei-go/nami 对照分析","description":"","frontmatter":{},"headers":[],"relativePath":"arch/nami/01-java-comparison.md","filePath":"arch/nami/01-java-comparison.md","lastUpdated":1787404550000}'),a={name:"arch/nami/01-java-comparison.md"};function r(n,e,i,l,s,g){return d(),o("div",null,[...e[0]||(e[0]=[c('<h1 id="solon-nami-与-aifei-go-nami-对照分析" tabindex="-1">Solon Nami 与 aifei-go/nami 对照分析 <a class="header-anchor" href="#solon-nami-与-aifei-go-nami-对照分析" aria-label="Permalink to &quot;Solon Nami 与 aifei-go/nami 对照分析&quot;">​</a></h1><blockquote><p>本文是「Nami 迁移到 Go」的对照分析。与 dami/flow 不同，nami 模块先于设计文档实现（直接照 <a href="https://solon.noear.org/" target="_blank" rel="noreferrer">Java Solon Nami</a> 移植），本文为<strong>回补文档</strong>：以 Solon 3.10.x 的 Nami 能力清单为基准，逐项对照 <code>./nami</code> 已实现的形态，标注移植状态与替代方案。 第二部分为契约设计文档 <a href="./02-design.html"><code>02-design.md</code></a>（as-built）。</p></blockquote><hr><h2 id="_1-solon-nami-是什么" tabindex="-1">1. Solon Nami 是什么 <a class="header-anchor" href="#_1-solon-nami-是什么" aria-label="Permalink to &quot;1. Solon Nami 是什么&quot;">​</a></h2><p><strong>一句话定位</strong>：<strong>声明式 RPC / HTTP 客户端</strong>框架——定义一个接口 + 注解，运行时动态代理把方法调用翻译成一次远程调用（HTTP 或 Socket.D），是 Solon 微服务体系的客户端半边。</p><p>它由三组正交抽象构成（Java 侧组件生态即按此切分）：</p><table tabindex="0"><thead><tr><th>抽象</th><th>Java 接口</th><th>生态组件</th></tr></thead><tbody><tr><td>传输通道</td><td><code>Channel</code></td><td><code>nami-channel-http</code>、<code>nami-channel-socketd</code></td></tr><tr><td>序列化</td><td><code>Encoder</code> / <code>Decoder</code></td><td><code>nami-coder-snack3</code> / <code>fastjson</code> / <code>fastjson2</code> / <code>jackson</code> / <code>hessian</code> / <code>fury</code> / <code>kryo</code> / <code>protostuff</code></td></tr><tr><td>拦截</td><td><code>Filter</code>（<code>doFilter(Invocation)</code>）</td><td>自带（接口自身 extends Filter）/ 全局（<code>@Component</code> 或 <code>NamiManager.reg</code>）</td></tr></tbody></table><p>外围是寻址与装配：<code>Upstream</code> / <code>Discovery</code> / <code>LoadBalance</code> 内核（<code>LoadBalance.get(group, service).getServer()</code>，与 httputils 共用）、<code>NamiBuilder</code> 构建器、<code>NamiManager</code> 全局注册表、<code>NamiConfiguration</code> 配置器。</p><h3 id="_1-1-java-侧核心能力清单-对照基准" tabindex="-1">1.1 Java 侧核心能力清单（对照基准） <a class="header-anchor" href="#_1-1-java-侧核心能力清单-对照基准" aria-label="Permalink to &quot;1.1 Java 侧核心能力清单（对照基准）&quot;">​</a></h3><ol><li><strong>声明式接口客户端</strong>：<code>@NamiClient</code> 注解在接口上，注入即用；字段 <code>url</code> / <code>group</code> / <code>name</code> / <code>path</code> / <code>headers</code> / <code>configuration</code> / <code>localFirst</code> / <code>timeout</code> / <code>heartbeat</code>。</li><li><strong>方法级映射</strong>：<code>@NamiMapping(&quot;GET&quot;)</code> / <code>@NamiMapping(&quot;PUT user/a.0.1&quot;)</code>；无注解时<strong>无参 GET、有参 POST</strong>，path 默认为函数名；v3.3 起可直接复用 Solon 注解（<code>@Post</code> / <code>@Mapping</code> / <code>@Consumes</code> / <code>@Header</code> / <code>@Cookie</code> / <code>@Path</code>）。</li><li><strong>参数级注解</strong>：<code>@NamiBody</code>（参数即请求体）、<code>@NamiParam</code>（参数名标注）。</li><li><strong>动态代理构建</strong>：<code>Nami.builder().name(&quot;userapi&quot;).path(&quot;/rpc/v1/user&quot;).encoder(...).decoder(...).create(UserService.class)</code>。</li><li><strong>Filter 两级作用域</strong>：接口自身 <code>extends Filter</code> + <code>default doFilter</code>（自身过滤器，可为不同站点定制编码策略）；<code>@Component</code> 全局过滤器；<code>NamiManager.reg(...)</code> 手动全局注册。filter 内可改 <code>inv.headers</code>、甚至换 <code>inv.config</code> 的 encoder/decoder。</li><li><strong>LoadBalance 内核</strong>：<code>LoadBalance.get(serviceName).getServer()</code>；策略可换（<code>CloudLoadStrategyDefault</code> 轮询 / <code>CloudLoadStrategyIpHash</code> / 自定义 <code>LoadBalance.Factory</code>）。</li><li><strong>服务发现</strong>：<code>@NamiClient(name=...)</code> 走发现（solon-cloud 本地发现，或 nacos/zookeeper/water 分布式发现），<code>url</code> 直连可不用发现。</li><li><strong>Socket.D 通道</strong>：<code>sd:tcp/ws/udp</code>，支持双向通信、<code>SocketdProxy.create(url, Iface)</code> 代理调用；<code>heartbeat</code> 仅对 socket/websocket 通道有效，<code>timeout</code> 全通道有效。</li><li><strong>配置器</strong>：<code>NamiConfiguration</code> 在容器里全局定制 encoder/decoder。</li><li><strong>localFirst</strong>：本地有接口实现时优先本地调用（单体→微服务平滑过渡）。</li></ol><hr><h2 id="_2-语言差异对移植的约束-必读" tabindex="-1">2. 语言差异对移植的约束（必读） <a class="header-anchor" href="#_2-语言差异对移植的约束-必读" aria-label="Permalink to &quot;2. 语言差异对移植的约束（必读）&quot;">​</a></h2><p>与 dami 迁移时（见 <a href="./../dami/01-go-comparison.html"><code>../dami/01-go-comparison.md</code></a> §2.8）同一组约束，但对 nami 更致命——因为<strong>声明式接口客户端就是 Nami 的主入口</strong>：</p><table tabindex="0"><thead><tr><th>Java 机制</th><th>Go 现实</th><th>对 nami 的影响</th></tr></thead><tbody><tr><td><code>java.lang.reflect.Proxy</code> 动态实现接口</td><td><strong>不可能</strong>（<a href="https://github.com/golang/go/issues/41897" target="_blank" rel="noreferrer">golang/go#41897</a> 被拒）；reflect 只能调用已有方法</td><td><code>Nami.builder().create(Iface.class)</code> 无法 1:1 移植——<strong>最大设计约束</strong></td></tr><tr><td>注解（<code>@NamiClient</code>/<code>@NamiMapping</code>/<code>@NamiBody</code>）</td><td>无注解</td><td>配置改走 Builder/Config 显式链式；方法映射改为调用点显式 <code>Action()</code></td></tr><tr><td><code>extends Filter</code> + <code>default</code> 方法（接口自带过滤器）</td><td>接口无默认实现</td><td>改为 <code>FilterFunc</code> 函数适配 + <code>Config.FilterAdd</code></td></tr><tr><td>SPI / 组件扫描（channel/coder 组件包）</td><td><code>init()</code> 自注册</td><td>import 子包即注册（Go 侧更轻）</td></tr><tr><td>运行时泛型擦除 + 反射解码</td><td>编译期泛型 + <code>reflect.Type</code></td><td>Go 侧反而更优：<code>util.GetJSON[T]</code> 编译期类型安全</td></tr></tbody></table><p><strong>Go 版的替代主线</strong>（详见 02-design.md）：动态代理 → <strong>流式 API</strong>（<code>Nami</code> 结构体：<code>Action/URL/Call*</code> 系列）+ <strong><code>ClientFactory.For(path)</code></strong>（一个服务一份模板配置，按路径克隆客户端）+ <strong><code>util</code> 泛型助手</strong>（<code>GetJSON[T]</code>/<code>PostJSON[T]</code>/<code>RequestJSON[T]</code>）。三者合起来覆盖 Java 声明式客户端的常用面，代价是失去&quot;接口即文档&quot;的声明式表达。</p><hr><h2 id="_3-能力移植矩阵" tabindex="-1">3. 能力移植矩阵 <a class="header-anchor" href="#_3-能力移植矩阵" aria-label="Permalink to &quot;3. 能力移植矩阵&quot;">​</a></h2><blockquote><p>图例：✅ 已移植；🟡 部分移植 / 有替代但语义有差；❌ 未移植。</p></blockquote><table tabindex="0"><thead><tr><th>#</th><th>Java Nami 能力</th><th>aifei-go/nami 对应</th><th style="text-align:center;">状态</th><th>说明</th></tr></thead><tbody><tr><td>1</td><td><code>Channel</code> 抽象</td><td><code>nami.Channel</code> 接口（<code>Call(ctx *Context)</code>）</td><td style="text-align:center;">✅</td><td>接口同构；通道按 URL scheme 从注册表解析</td></tr><tr><td>2</td><td>HTTP 通道</td><td><code>channel/http</code>（<code>init()</code> 注册 <code>http</code>/<code>https</code>）</td><td style="text-align:center;">✅</td><td>基于 <code>net/http</code>；默认 30s 超时，可换 <code>*http.Client</code></td></tr><tr><td>3</td><td>Socket.D 通道</td><td>—</td><td style="text-align:center;">❌</td><td>未移植；<code>joinURI</code> 预留了 <code>sd:</code> 前缀剥离，将来可加 <code>channel/socketd</code></td></tr><tr><td>4</td><td><code>Encoder</code>/<code>Decoder</code> 抽象</td><td><code>nami.Encoder</code>/<code>nami.Decoder</code>（<code>Enctype</code>/<code>BodyRequired</code>/<code>Pretreatment</code>）</td><td style="text-align:center;">✅</td><td>接口同构，多出 <code>Pretreatment</code> 显式化为方法</td></tr><tr><td>5</td><td>编解码生态（8 种序列化）</td><td><code>coder/json</code>（唯一内置，纯标准库）</td><td style="text-align:center;">🟡</td><td>只内置 JSON；hessian/kryo/protobuf 等按需自实现 <code>Encoder</code>/<code>Decoder</code> 注册即可</td></tr><tr><td>6</td><td>内容类型驱动编解码选择</td><td><code>manager.go</code> 按 <code>Enctype()</code> 注册 + header（<code>Content-Type</code>/<code>Accept</code>）反查</td><td style="text-align:center;">✅</td><td><code>RegEncoderIfAbsent</code> 等兜底注册语义保留</td></tr><tr><td>7</td><td>Filter（自身/全局）</td><td><code>Config.FilterAdd</code>（每客户端）+ <code>nami.RegFilter</code>（全局）</td><td style="text-align:center;">🟡</td><td>全局注册表已有，但 <code>RegFilter</code>/<code>GetFilters</code> <strong>尚未接线进调用链</strong>（见 02-design.md §7）</td></tr><tr><td>8</td><td><code>Invocation</code> 过滤器链</td><td><code>nami.Invocation</code>（内嵌 <code>Context</code>，index 游标链 + actuator）</td><td style="text-align:center;">✅</td><td>链序 = 配置注册序，末位是通道执行器</td></tr><tr><td>9</td><td><code>@NamiClient</code> 注解配置</td><td><code>Builder</code> / <code>Config</code> 显式链式（<code>URL/Name/Path/Group/HeaderSet/Timeout/FilterAdd</code>）</td><td style="text-align:center;">🟡</td><td>字段一一对应（url/name/group/path/headers/timeout），显式替代注解</td></tr><tr><td>10</td><td>接口代理 <code>create(Iface)</code></td><td>流式 <code>Nami</code> + <code>ClientFactory.For(path)</code> + <code>util.GetJSON[T]</code></td><td style="text-align:center;">🟡</td><td>语言限制下的替代主线（见上）</td></tr><tr><td>11</td><td><code>@NamiMapping</code> 方法映射（默认 GET/POST、path=函数名）</td><td><code>Action(&quot;GET&quot;)</code> 显式设置（默认 POST）+ <code>URLWithPath</code> 的 <code>{fun}</code> 占位符</td><td style="text-align:center;">🟡</td><td>无方法级声明；<code>{fun}</code> 保留了&quot;url 模板 + 函数名替换&quot;的味道</td></tr><tr><td>12</td><td><code>@NamiBody</code>/<code>@NamiParam</code></td><td><code>Call(headers, args, body)</code> 三参显式分离</td><td style="text-align:center;">🟡</td><td>body/args（query 或 form）/headers 显式传</td></tr><tr><td>13</td><td><code>timeout</code>（全通道）</td><td><code>Config.Timeout</code>（秒）→ HTTP 通道每请求新建 client 生效</td><td style="text-align:center;">✅</td><td>语义一致</td></tr><tr><td>14</td><td><code>heartbeat</code>（仅 socket 通道）</td><td><code>Config.Heartbeat</code> 字段 + Builder/Factory setter</td><td style="text-align:center;">🟡</td><td><strong>预留字段</strong>：HTTP 通道不消费（对齐 Java 侧&quot;仅 socket 有效&quot;；无 socket 通道故闲置）</td></tr><tr><td>15</td><td>LoadBalance 内核 + 策略</td><td><code>Upstream func() string</code> + <code>UpstreamFixed</code>（多实例轮询、单实例无锁闭包）</td><td style="text-align:center;">🟡</td><td>轮询有；ip-hash 等策略无。一等 <code>Balancer</code> 契约规划在 <a href="./../microservice.html"><code>../microservice.md</code></a> P0-A</td></tr><tr><td>16</td><td><code>Discovery</code> 发现接口</td><td><code>nami.Discovery</code>（<code>GetServer(group, name)</code>）+ <code>NewDiscoveryUpstream</code> 桥接</td><td style="text-align:center;">✅</td><td><a href="./../../guide/nacos.html">plugins/nacos</a> <code>NewNamiUpstream</code> 即此接入点（当前固定取第一个实例——已知缺口，P0-A 修）</td></tr><tr><td>17</td><td><code>NamiManager</code> 全局注册表</td><td><code>manager.go</code>（<code>RegChannel/RegEncoder/RegDecoder/RegFilter</code> + <code>Get*First</code>）</td><td style="text-align:center;">✅</td><td>&quot;首个注册者为默认&quot;语义保留</td></tr><tr><td>18</td><td><code>NamiConfiguration</code> 配置器</td><td>—</td><td style="text-align:center;">❌</td><td>无容器概念，不需要；Builder 即配置器</td></tr><tr><td>19</td><td><code>localFirst</code> 本地优先</td><td>—</td><td style="text-align:center;">❌</td><td>未移植；单体场景用 <a href="./../../guide/dami.html">dami</a> lpc 或直接函数调用更 Go 味</td></tr><tr><td>20</td><td><code>Result</code> 响应包装</td><td><code>nami.Result</code>（code/headers/charset/body + <code>Bind</code>/<code>AsAny</code>/<code>AssertSuccess</code>）</td><td style="text-align:center;">✅</td><td>Go 版把&quot;检查 2xx + 解码&quot;上提为 <code>Result</code> 方法，更顺手；注意 <code>Bind</code> 直用 <code>encoding/json</code> 而非 <code>Decoder</code>（差异见 02-design.md §3.5）</td></tr></tbody></table><p><strong>总评</strong>：传输/序列化/拦截三组核心抽象与注册表机制完整落地（✅ 占多数）；缺口集中在两类——<strong>语言不可为</strong>（接口代理 → 流式 API 替代）与<strong>生态未铺</strong>（Socket.D 通道、多序列化、LB 策略、全局 Filter 接线）。后者全部登记在 02-design.md §7 的限制清单与 microservice.md 路线图中。</p><hr><h2 id="_4-定位对照-nami-在-aifei-go-里的角色" tabindex="-1">4. 定位对照：nami 在 aifei-go 里的角色 <a class="header-anchor" href="#_4-定位对照-nami-在-aifei-go-里的角色" aria-label="Permalink to &quot;4. 定位对照：nami 在 aifei-go 里的角色&quot;">​</a></h2><p>Java Solon 体系里 Nami 是独立客户端框架（<code>org.noear:nami</code>），与 Solon 服务端解耦。aifei-go 保持了这个定位，并与兄弟模块形成三层&quot;调用&quot;光谱：</p><table tabindex="0"><thead><tr><th>调用方式</th><th>模块</th><th>走网络</th><th>形态</th></tr></thead><tbody><tr><td>进程内解耦调用</td><td><a href="./../../guide/dami.html">dami</a></td><td>❌</td><td>事件总线 / lpc</td></tr><tr><td><strong>跨进程 RPC 调用</strong></td><td><strong><a href="./../../guide/nami.html">nami</a></strong></td><td>✅ HTTP</td><td>流式客户端 + Channel/Coder/Filter/Upstream</td></tr><tr><td>服务端暴露</td><td><a href="./../../guide/core.html">aifei</a> + <a href="./../../guide/server.html">server</a></td><td>—</td><td>Just Service 路由</td></tr></tbody></table><p>nami 是 aifei 服务端的<strong>对偶</strong>：aifei <code>{code,msg,data}</code> JSON 出口 ↔ nami <code>Result.Bind</code> JSON 入口；<a href="./../../guide/nacos.html">nacos 插件</a>在中间提供注册/发现，把两端接成微服务闭环。</p><hr><h2 id="_5-结论" tabindex="-1">5. 结论 <a class="header-anchor" href="#_5-结论" aria-label="Permalink to &quot;5. 结论&quot;">​</a></h2><ol><li><strong>三组正交抽象是 Nami 的骨架，Go 版完整保留</strong>——Channel / Encoder+Decoder / Filter 接口与 Java 侧一一同构，注册表机制（含 <code>*IfAbsent</code>、First-default）语义对齐。</li><li><strong>声明式接口客户端不可移植是唯一硬约束</strong>，Go 版用「流式 API + ClientFactory + util 泛型助手」三件套覆盖其常用面，并换来编译期类型安全。</li><li><strong>Java 的注解配置 ↔ Go 的 Builder 链式</strong>是全局替代关系：<code>@NamiClient</code> 的每个字段在 <code>Builder</code>/<code>Config</code> 上都有同名方法。</li><li>剩余缺口（Socket.D、多序列化 coder、LB 策略、全局 Filter 接线、heartbeat 消费）均为<strong>生态铺量工作</strong>而非设计障碍，优先级见 <a href="./02-design.html"><code>02-design.md</code></a> §7 与 <a href="./../microservice.html"><code>../microservice.md</code></a>。</li></ol><p>契约与调用时序的 as-built 细节见 <a href="./02-design.html"><code>02-design.md</code></a>。</p><hr><h2 id="参考资料" tabindex="-1">参考资料 <a class="header-anchor" href="#参考资料" aria-label="Permalink to &quot;参考资料&quot;">​</a></h2><ul><li>Solon Nami 官方文档（RPC / Nami 注解 / 过滤器 / LoadBalance）：<a href="https://solon.noear.org/" target="_blank" rel="noreferrer">https://solon.noear.org/</a>（remoting 章节）</li><li>Solon 源码：<a href="https://github.com/opensolon/solon" target="_blank" rel="noreferrer">https://github.com/opensolon/solon</a>（<code>nami</code> 内核 + channel/coder 组件）</li><li>本仓库 Go 实现：<code>nami/</code>（见 <a href="./02-design.html"><code>02-design.md</code></a> 模块清单）</li><li>动态代理提案：<a href="https://github.com/golang/go/issues/41897" target="_blank" rel="noreferrer">golang/go#41897</a></li><li>姊妹篇：<a href="./../dami/01-go-comparison.html"><code>../dami/01-go-comparison.md</code></a>（含 Go 动态代理能力分析 §2.8）</li></ul>',32)])])}const u=t(a,[["render",r]]);export{h as __pageData,u as default};
